                    operation: "read",
                    path: path.to_path_buf(),
                    source: Arc::new(std::io::Error::new(
                        std::io::ErrorKind::InvalidInput,
                        "path outside configured roots",
                    )),
                    kind: std::io::ErrorKind::InvalidInput,
                });
            }

