        }
        Ordering::ByFileThenScore => {
            parts.sort_by(|a, b| match a.file_path.cmp(&b.file_path) {
                std::cmp::Ordering::Equal => match b
                    .score
                    .partial_cmp(&a.score)
                    .unwrap_or(std::cmp::Ordering::Equal)
