    // If already within budget, return early.
    if tokenizer.count(text) <= max_tokens {
        return (text.to_string(), false);
    }

    // Use binary search to find the optimal truncation point.
    // This reduces O(n*m) worst case to O(n*log(n)).
    let chars: Vec<char> = text.chars().collect();
    let total_chars = chars.len();

    // Binary search for the maximum chars that fit within the token budget.
    let mut low = 0usize;
