        first_row,
        "LastRow number ",
        j,
        last_row,
    );
    tracing::trace!(
        "{:=^80}\n{:=^30}ATOMIC COUNTER: {:?}\n{:=^30}{:=^80}",
        "",
        "",
        counter,
        "",
        ""
    );
}

