    match format!("{evidence:?}").as_str() {
        "Projection" => Color32::from_rgb(214, 228, 255),
        "TypedRecord" => Color32::from_rgb(218, 243, 224),
        "AdmittedHistory" => Color32::from_rgb(252, 235, 200),
