        assert_eq!(tools.len(), 2);
        assert_eq!(tools[0].name, "git_status");
        assert_eq!(tools[0].description.as_deref(), Some("List status"));
        assert_eq!(tools[1].name, "git_diff");
        assert!(tools[1].description.is_none());
    }
}

