        (
            key.clone(),
            ArtifactNode {
                key,
                identity: ArtifactIdentity::HistoryRef(artifact),
                ids: ArtifactIds {
                    artifact_refs: vec![ArtifactRefRecord::from_artifact_id(
                        ploke_records::ids::ArtifactId(value.to_owned()),
