        #[instrument(skip_all, fields(source = ?self.source, target = "embed-pipeline"))]
    pub async fn generate_embeddings_with_cancel(
        &self,
        snippets: Vec<String>,
        cancel: Option<&CancellationListener>,
    ) -> Result<Vec<Vec<f32>>, EmbedError> {
        tracing::trace!(target: "embed-pipeline", "Starting generate_embeddings with EmbeddingSource dimensions: {:#?} with {} snippets\nfirst snippet: {:?}\nlast snippet: {:?}",
            self.dimensions(),
            snippets.len(),
            snippets.first(),
            snippets.last(),
        );
        if snippets.is_empty() {
            return Ok(Vec::new());
        }

        let chunk_cap = self.snippet_batch_size();
        if snippets.len() <= chunk_cap {
            return self.dispatch_embeddings_single(snippets, cancel).await;
        }

        // Optimized sequential processing with pre-allocated capacity
        // Calculate total expected embeddings for optimal pre-allocation
        let mut all_embeddings = Vec::with_capacity(snippets.len());

        // Process all chunks sequentially - each chunk is independent
        for chunk in snippets.chunks(chunk_cap) {
            let part = self.dispatch_embeddings_single(chunk.to_vec(), cancel).await?;
            all_embeddings.extend(part);
        }

        Ok(all_embeddings)
    }

    /// Max snippets to send per backend request (processor splits larger inputs).
    pub fn snippet_batch_size(&self) -> usize {
        match &self.source {
            EmbeddingSource::Local(backend) => backend.snippet_batch_size(),
            EmbeddingSource::OpenRouter(backend) => backend.snippet_batch_size,
            EmbeddingSource::HuggingFace(_) => 64,
            EmbeddingSource::OpenAI(_) => 100,
            EmbeddingSource::Cozo(_) => 32,
        }
    }

    async fn dispatch_embeddings_single(
        &self,
        snippets: Vec<String>,
        cancel: Option<&CancellationListener>,
    ) -> Result<Vec<Vec<f32>>, EmbedError> {
        match &self.source {
            EmbeddingSource::Local(backend) => {
                let text_slices: Vec<&str> = snippets.iter().map(|s| s.as_str()).collect();
                Ok(backend
                    .embed_batch(&text_slices)
                    .inspect(|v| {
                        tracing::trace!("OK Returning from embed_batch with vec(s): {:?}", v);
                    })
                    .inspect_err(|e| {
                        tracing::trace!(
                            "Error Returning from embed_batch with error: {:?}",
                            e.to_string()
                        );
                    })?)
            }
            EmbeddingSource::HuggingFace(backend) => backend.compute_batch(snippets).await,
            EmbeddingSource::OpenAI(backend) => backend.compute_batch(snippets).await,
            EmbeddingSource::OpenRouter(backend) => backend.compute_batch(snippets, cancel).await,
            EmbeddingSource::Cozo(backend) => backend.compute_batch(snippets).await,
        }
    }

    pub fn dimensions(&self) -> usize {
        match &self.source {
            EmbeddingSource::Local(backend) => backend.dimensions(),
            EmbeddingSource::HuggingFace(backend) => backend.dimensions,
            EmbeddingSource::OpenAI(backend) => backend.dimensions,
            EmbeddingSource::OpenRouter(backend) => backend.dimensions,
            EmbeddingSource::Cozo(backend) => backend.dimensions,
        }
    }
}

