            payload_index: 0,
            branch_id: "branch".to_owned(),
            candidate_id: None,
            source_state_id: None,
            parent_branch_id: None,
            base_artifact_id: Some(ArtifactId(base.to_owned())),
            derived_artifact_id: Some(ArtifactId(derived.to_owned())),
