                "type": "boolean",
                "description": BINS_DESC
            },
            "examples": {
                "type": "boolean",
                "description": EXAMPLES_DESC
            },
            "benches": {
                "type": "boolean",
                "description": BENCHES_DESC
            },
            "test_args": {
