        "profile-ingest-help" => {
            print_profile_ingest_help();
            Ok(())
        }
        _ => {
            let cli = cli::Cli::try_parse_from(args).map_err(DispatchError::Clap)?;
            cli.execute().map_err(DispatchError::Xtask)
        }
    }
}

