                    let hc_timeout =
                        Duration::from_millis(spec.default_timeout_ms.unwrap_or(30_000).min(5_000));
                    match Self::health_check(id, &service, hc_timeout).await {
                        Ok(()) => return Ok(service),
                        Err(e) => {
