            let base = 500u64;
            let backoff_ms = (base.saturating_mul(1u64 << attempt.min(4))) // 500,1_000,2_000,4_000,8_000
                .min(8_000);
            let jitter: u64 = rand::thread_rng().gen_range(0..=250);
