            max_generations: 1,
            max_total_nodes: 32,
            children: ChildBudgetRecord::default(),
            schedule: ChildScheduleModeRecord::default(),
            stop_on_first_keep: false,
            require_keep_for_continuation: true,
            explore_from_rejected: true,
        }
    }
}

