                        },
                    ),
                    (
                        side_lineage.clone(),
                        LineageNode {
                            lineage_id: side_lineage.clone(),
                            blocks: vec![side_block.clone()],
                        },
                    ),
                ]),
                blocks: BTreeMap::from([
                    (
                        block_one.clone(),
                        history_block_in(
                            block_one,
                            lineage.clone(),
