            per_file_max: 4096,
            per_part_max: 2048,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Ordering {
    /// Order by fused score (desc), tie-break by UUID asc.
    FusedScoreThenStructure,
    /// Group by file, within each group order by score (desc), tie-break by UUID asc.
    ByFileThenScore,
}

