                "Command '{}' not found on PATH",
                spec.command
            )));
        }
        let child = TokioChildProcess::new(Command::new(&spec.command).configure(|cmd| {
            if !spec.args.is_empty() {
                cmd.args(&spec.args);
            }
            if !spec.env.is_empty() {
