        .map_err(|e| McpError::Spawn(format!("Failed to launch '{}': {}", spec.command, e)))?;

        let service = ().serve(child).await.map_err(|e| {
            McpError::Transport(format!("Failed to connect to '{}': {}", spec.id, e))
        })?;

        info!("Connected to server process");
        Ok(service)
    }
}

