                        .fan_out_named("context", "intent_segmentation", segment)
                        .merge(normalize),
                )
                .named("tool_call_intent_segmentation"),
        }
    }
}

#[cfg(feature = "llm")]
#[async_trait]
impl Procedure for ToolCallIntentSegmentation {
    type Subject = ToolCallSequence;
