                            "artifact:side",
                            "artifact:side",
                        ),
                    ),
                ]),
                ..HistoryIndex::default()
            },
            ..Graph::default()
        };

        let tree = graph.artifact_tree();

        assert_eq!(
            tree.marks
                .primary_lineage
                .map(|lineage| lineage.lineage_id.0.as_str()),
