        );
        assert_eq!(
            key_strings(&tree.marks.lineage_artifacts),
            vec!["base", "leaf", "middle"]
        );
        assert_eq!(
            tree.marks
                .lineage_edges
                .iter()
                .map(|(from, to)| (from.as_str(), to.as_str()))
