impl EmbeddingProcessor {
    pub fn new(source: EmbeddingSource) -> Self {
        Self { source }
    }

    /// Create a lightweight mock embedder for tests.
    /// Uses the Cozo backend placeholder with a fixed dimension.
    pub fn new_mock() -> Self {
        Self {
