    pub target: Option<Cow<'a, str>>,
    #[serde(default, borrow)]
    pub profile: Option<Cow<'a, str>>,
    #[serde(default)]
    pub release: bool,
    #[serde(default)]
    pub lib: bool,
    #[serde(default)]
    pub tests: bool,
    #[serde(default)]
    pub bins: bool,
    #[serde(default)]
    pub examples: bool,
    #[serde(default)]
    pub benches: bool,
    #[serde(default, borrow)]
    pub test_args: Option<Vec<Cow<'a, str>>>,
}

