                            "Failed to serialize list_tools response: {}",
                            e
                        ))
                    })?;
                    let tools = Self::map_tools_from_value(&val)?;
                    return Ok(tools);
                }
                Err(err) => {
                    attempt += 1;
                    if attempt >= max_attempts {
                        return Err(err);
                    }
