            Some(crate::clients::context7::Context7Client::new(self))
        } else {
            None
        }
    }

    /// Convenience: get a typed Git client if configured.
    pub fn client_git(&self) -> Option<crate::clients::git::GitClient<'_>> {
        let id: ServerId = "git".into();
