        }
    }

    /// Best-effort respawn: cancel existing (if any), then spawn_with_backoff and insert.
    async fn respawn_with_backoff(&self, id: &ServerId, spec: &ServerSpec) -> Result<(), McpError> {
        if let Some((_, old)) = self.registry.remove(id) {
