        if tokens <= max_tokens {
            low = mid;  // This fits, try more chars
        } else {
            high = mid - 1;  // Too many tokens, try fewer chars
        }
    }

    // low is now the max chars that fit within the token budget.
    let final_chars = low;
    let truncated = final_chars < total_chars;
    let result: String = chars[..final_chars].iter().collect();

    (result, truncated)
